  1	// One fulfilment (SPEC-E R4.2 saga, R4.4 carrier reports, R5.1 compensation, R5.2 failure, S14). Key = fulfilment id.
  2	// Steps: reserve every item (one batch, each item keyed) → charge → ship. A failing or cancelled fulfilment is
  3	// compensated in reverse order of what committed: shipment, charge (refund), reservations (release). Whenever a step
  4	// commits after the stop, it is compensated as well (S14, R6.2). Nothing new is started once stopped.
  5	
  6	const fileJson = (files, p) => {
  7	  let v = files?.[p];
  8	  if (v === undefined) v = p.split('/').reduce((o, k) => (o ? o[k] : undefined), files);
  9	  if (typeof v === 'string') { try { v = JSON.parse(v); } catch { return null; } }
 10	  return v ?? null;
 11	};
 12	
 13	const MAX_FIX = 3;
 14	
 15	// A 400 from a system is our mistake (e.g. a field it renamed): re-issue with the arguments the current schema names.
 16	const fixArgs = (v, s) => {
 17	  if (!s || v === null || typeof v !== 'object') return v;
 18	  if (Array.isArray(v)) return v.map(x => fixArgs(x, s.items));
 19	  const props = Object.keys(s.properties ?? {});
 20	  if (!props.length) return v;
 21	  const out = {}, extra = [];
 22	  for (const k of Object.keys(v)) (props.includes(k) ? (out[k] = fixArgs(v[k], s.properties[k])) : extra.push(k));
 23	  const missing = (s.required ?? []).filter(k => !(k in out));
 24	  extra.forEach((k, i) => { if (missing[i]) out[missing[i]] = fixArgs(v[k], s.properties[missing[i]]); });
 25	  return out;
 26	};
 27	const argsSchema = (ctx, system, op) => fileJson(ctx.files, `api/${system}.schema.json`)?.ops?.[op]?.args ?? null;
 28	
 29	const codeOf = err => (typeof err === 'string' ? err : err?.code);
 30	const isInvalid = err => codeOf(err) === 'invalid-args' || codeOf(err) === 'field-renamed';
 31	// a permanent error (retryable: false, a declined card, a permanent failure) is never retried; any other error is
 32	// retried a few times (the platform has already retried it once, e.g. 503 batch-item-not-processed)
 33	const isTransient = err => {
 34	  const c = String(codeOf(err) ?? '');
 35	  return !/permanent|declined/.test(c) && !(typeof err === 'object' && err !== null && err.retryable === false);
 36	};
 37	// a budget of re-issues per step, so one step's renames do not use up another step's retries
 38	const tryAgain = (S, step) => { S.fx[step] = (S.fx[step] ?? 0) + 1; return S.fx[step] <= MAX_FIX; };
 39	
 40	// ok | pend (still running) | invalid (our request was wrong) | bad (a permanent failure) | transient (retry later)
 41	const classify = (ctx, system, key, status, err) => {
 42	  if (status === 'ok') return 'ok';
 43	  if (status === 'unknown') {
 44	    const s = ctx.status(system, key);       // S2: committed is the system's truth, not what we last saw
 45	    return s === 'committed' ? 'ok' : s === 'pending' ? 'pend' : 'bad';
 46	  }
 47	  if (status === 'error') return isInvalid(err) ? 'invalid' : isTransient(err) ? 'transient' : 'bad';
 48	  return 'pend';
 49	};
 50	
 51	const reserveEffect = (S, skus, args) => ({
 52	  system: 'inventory', op: 'reserve',
 53	  args: args ?? { orderId: S.f.oid, fulfilmentId: S.f.fid, location: S.f.loc,
 54	    items: skus.map(sku => ({ key: `r.${sku}`, sku, qty: S.f.qty[sku] })) },
 55	});
 56	const chargeArgs = S => ({ orderId: S.f.oid, fulfilmentId: S.f.fid, customerId: S.f.cust, amountMinor: S.f.amt, currency: S.f.cur });
 57	const shipArgs = S => ({ orderId: S.f.oid, fulfilmentId: S.f.fid, location: S.f.loc, ref: S.f.fid });
 58	const setStatus = (S, status, key) => ({ key, system: 'orders', op: 'setStatus', args: { orderId: S.f.oid, fulfilmentId: S.f.fid, status } });
 59	
 60	// Compensation (R5.1) of everything committed and not yet undone, then the terminal status once nothing is in flight.
 61	function settle(S, at, ctx) {
 62	  const eff = [];
 63	  // nothing is undone unless the fulfilment was stopped by a failure or a cancel (never after a normal completion)
 64	  if (!S.sr) return { eff, ended: null };
 65	  const waitShip = S.sh === 'pend', waitCharge = S.ch === 'pend';
 66	  // R5.1 order: shipment, then charge, then reservations; each waits for an in-flight step before it is undone
 67	  if (!waitShip) {
 68	    if (S.sh === 'ok' && !S.sc && !S.cf) { S.sc = true; eff.push({ key: 'ship.cancel', system: 'carrier', op: 'cancel', args: { orderId: S.f.oid, fulfilmentId: S.f.fid } }); }
 69	    if (!waitCharge) {
 70	      if (S.ch === 'ok' && !S.rf) { S.rf = true; eff.push({ key: 'refund', system: 'billing', op: 'refund', args: { orderId: S.f.oid, fulfilmentId: S.f.fid, amountMinor: S.f.amt } }); }
 71	      for (const [sku, r] of Object.entries(S.res)) {
 72	        if (r.s === 'ok' && !r.rel) { r.rel = true; eff.push({ key: `rel.${sku}`, system: 'inventory', op: 'release', args: { orderId: S.f.oid, fulfilmentId: S.f.fid, sku } }); }
 73	      }
 74	    }
 75	  }
 76	  const busy = Object.values(S.res).some(r => r.s === 'pend') || waitCharge || waitShip;
 77	  let ended = null;
 78	  if (S.st === 'stop' && !busy && !S.sf) {
 79	    S.sf = true; S.st = 'end';
 80	    const status = S.sr === 'fail' ? 'failed' : 'cancelled';
 81	    S.ev = status;
 82	    eff.push(setStatus(S, status, `st.${status}`));
 83	    if (status === 'failed') eff.push({ key: 'n.failed', system: 'notify', op: 'send', args: { to: S.f.em, about: S.f.fid, template: 'fulfilment-failed', text: `Fulfilment ${S.f.fid} of order ${S.f.oid} could not be completed.`, ref: null } });
 84	    ended = { fid: S.f.fid, status, at };
 85	  }
 86	  return { eff, ended };
 87	}
 88	
 89	const stopWith = (S, reason, at) => { if (S.st === 'run') { S.st = 'stop'; S.sr = reason; S.sat = at; } };
 90	
 91	export function step(input, ctx) {
 92	  let S = ctx.state;
 93	  if (input.op === 'start') {
 94	    if (S) return { output: null, state: S };
 95	    const f = input.fulfilment;
 96	    const qty = {};
 97	    for (const it of f.items) qty[it.sku] = (qty[it.sku] ?? 0) + it.qty;
 98	    const res = {};
 99	    for (const sku of Object.keys(qty)) res[sku] = { s: 'pend', n: 0, rel: false };
100	    S = { st: 'run', sr: null, f: { oid: f.orderId, fid: f.fulfilmentId, loc: f.location, cust: f.customerId, cur: f.currency, amt: f.amountMinor, em: f.email, qty }, res, ch: 'none', sh: 'none', sc: false, rf: false, cf: false, dp: false, sf: false, fx: {} };
101	    return { output: null, state: S, effects: [reserveEffect(S, Object.keys(res))] };
102	  }
103	  if (input.op === 'resume') {
104	    // go-live (§3.5): a fulfilment in flight continues from its records; committed steps are not repeated, the rest
105	    // are issued again with their stable keys (a committed key returns the original result)
106	    if (S) return { output: null, state: S };
107	    const f = input.fulfilment;
108	    const qty = {};
109	    for (const it of f.items) qty[it.sku] = (qty[it.sku] ?? 0) + it.qty;
110	    const res = {};
111	    for (const sku of Object.keys(qty)) res[sku] = { s: input.reserved.includes(sku) ? 'ok' : 'pend', n: 0, rel: false };
112	    S = { st: 'run', sr: null, f: { oid: f.orderId, fid: f.fulfilmentId, loc: f.location, cust: f.customerId, cur: f.currency, amt: f.amountMinor, em: f.email, qty }, res,
113	      ch: input.charged ? 'ok' : 'none', sh: input.shipped ? 'ok' : 'none', sc: false, rf: false, cf: false, dp: !!input.dispatched, sf: false, fx: {} };
114	    const pend = Object.keys(res).filter(sku => res[sku].s === 'pend');
115	    const eff = [];
116	    if (pend.length) eff.push(reserveEffect(S, pend));
117	    else if (S.ch === 'none') { S.ch = 'pend'; eff.push({ key: 'charge', system: 'billing', op: 'charge', args: chargeArgs(S) }); }
118	    else if (S.sh === 'none') { S.sh = 'pend'; eff.push({ key: 'ship', system: 'carrier', op: 'create', args: shipArgs(S) }); }
119	    return { output: null, state: S, effects: eff };
120	  }
121	  if (!S) return { output: null, state: null };
122	  if (input.op === 'carrier') {
123	    // a report about a shipment we cancelled, or a fulfilment already ended, changes nothing (§3.3)
124	    if (S.st !== 'run' || S.sh !== 'ok') return { output: null, state: S };
125	    const m = input.report.meaning, at = input.report.reportedAt, eff = [];
126	    let ended = null;
127	    if (m === 'collectionFailed') { S.cf = true; stopWith(S, 'fail', at); }
128	    else if (m === 'collected') { if (!S.dp) { S.dp = true; eff.push(setStatus(S, 'dispatched', 'st.dispatched')); } }
129	    else if (m === 'delivered') {
130	      if (!S.dp) { S.dp = true; eff.push(setStatus(S, 'dispatched', 'st.dispatched')); }
131	      eff.push(setStatus(S, 'completed', 'st.completed'));
132	      S.st = 'end'; S.ev = 'completed';
133	      ended = { fid: S.f.fid, status: 'completed', at };
134	    }
135	    const r = settle(S, at, ctx);
136	    return { output: { ended: ended ?? r.ended }, state: S, effects: eff.concat(r.eff) };
137	  }
138	  if (input.op === 'cancel') {
139	    if (!S || S.st === 'end') return { output: null, state: S };
140	    if (S.st === 'run' && S.ch === 'none' && S.sh === 'none' && Object.values(S.res).every(r => r.s !== 'ok' && r.s !== 'pend')) {
141	      // nothing started: nothing to undo
142	      S.st = 'end'; S.sf = true; S.ev = 'cancelled';
143	      return { output: { ended: { fid: S.f.fid, status: 'cancelled', at: input.at } }, state: S, effects: [setStatus(S, 'cancelled', 'st.cancelled')] };
144	    }
145	    stopWith(S, 'cancel', input.at);
146	    const r = settle(S, input.at, ctx);
147	    return { output: { ended: r.ended }, state: S, effects: r.eff };
148	  }
149	  throw new Error(`fulfilment: unknown op ${input.op}`);
150	}
151	
152	export function onEvent(event, ctx) {
153	  const S = ctx.state;
154	  const p = event.payload ?? {};
155	  if (!S || event.type !== 'effect.result') return { output: { ended: null }, state: S };
156	  const sys = `${p.system}.${p.op}`;
157	  const at = event.at;
158	  const eff = [];
159	  let ended = null;
160	  const fail = () => stopWith(S, 'fail', at);
161	
162	  if (sys === 'inventory.reserve') {
163	    const items = Array.isArray(p.items) ? p.items : Object.keys(S.res).filter(k => S.res[k].s === 'pend').map(sku => ({ key: `r.${sku}`, status: p.status, error: p.error }));
164	    const redo = [], fixable = [];
165	    for (const it of items) {
166	      const sku = String(it.key ?? '').replace(/^r\./, '');
167	      const r = S.res[sku];
168	      if (!r || r.s !== 'pend') continue;
169	      const c = classify(ctx, 'inventory', `r.${sku}`, it.status ?? p.status, it.error ?? p.error);
170	      if (c === 'ok') r.s = 'ok';
171	      else if (c === 'invalid') fixable.push(sku);
172	      else if (c === 'transient' && r.n < MAX_FIX) { r.n += 1; redo.push(sku); }
173	      else if (c === 'bad' || c === 'transient') { r.s = 'bad'; fail(); }
174	    }
175	    if (fixable.length) {
176	      const fixed = fixArgs(reserveEffect(S, fixable).args, argsSchema(ctx, 'inventory', 'reserve'));
177	      const e = tryAgain(S, 'reserve') ? reserveEffect(S, fixable, fixed) : false;
178	      if (e) eff.push(e); else { for (const sku of fixable) S.res[sku].s = 'bad'; fail(); }
179	    }
180	    if (redo.length) eff.push(reserveEffect(S, redo));
181	    if (Object.values(S.res).every(r => r.s === 'ok') && S.st === 'run') {
182	      // all reserved: charge; if the charge was already committed (a go-live resume), book the shipment instead
183	      if (S.ch === 'none') { S.ch = 'pend'; eff.push({ key: 'charge', system: 'billing', op: 'charge', args: chargeArgs(S) }); }
184	      else if (S.ch === 'ok' && S.sh === 'none') { S.sh = 'pend'; eff.push({ key: 'ship', system: 'carrier', op: 'create', args: shipArgs(S) }); }
185	    }
186	  } else if (sys === 'billing.charge') {
187	    const c = classify(ctx, 'billing', 'charge', p.status, p.error);
188	    if (c === 'ok') {
189	      S.ch = 'ok';
190	      if (S.st === 'run') { S.sh = 'pend'; eff.push({ key: 'ship', system: 'carrier', op: 'create', args: shipArgs(S) }); }
191	    } else if (c === 'invalid') {
192	      const fixed = fixArgs(chargeArgs(S), argsSchema(ctx, 'billing', 'charge'));
193	      if (tryAgain(S, 'charge')) eff.push({ key: 'charge', system: 'billing', op: 'charge', args: fixed }); else { S.ch = 'bad'; fail(); }
194	    } else if (c === 'bad') { S.ch = 'bad'; fail(); }
195	    else if (c === 'transient' && tryAgain(S, 'charge')) eff.push({ key: 'charge', system: 'billing', op: 'charge', args: chargeArgs(S) });
196	    else if (c === 'transient') { S.ch = 'bad'; fail(); }
197	  } else if (sys === 'carrier.create') {
198	    const c = classify(ctx, 'carrier', 'ship', p.status, p.error);
199	    if (c === 'ok') S.sh = 'ok';
200	    else if (c === 'invalid') {
201	      const fixed = fixArgs(shipArgs(S), argsSchema(ctx, 'carrier', 'create'));
202	      if (tryAgain(S, 'ship')) eff.push({ key: 'ship', system: 'carrier', op: 'create', args: fixed }); else { S.sh = 'bad'; fail(); }
203	    } else if (c === 'bad') { S.sh = 'bad'; fail(); }
204	    else if (c === 'transient' && tryAgain(S, 'ship')) eff.push({ key: 'ship', system: 'carrier', op: 'create', args: shipArgs(S) });
205	    else if (c === 'transient') { S.sh = 'bad'; fail(); }
206	  }
207	  // refunds, releases, cancellations and status changes need no reply from us: nothing else to decide
208	  const r = settle(S, at, ctx);
209	  ended = r.ended;
210	  return { output: { ended }, state: S, effects: eff.concat(r.eff) };
211	}

