----
     1	// Intake (SPEC-E R1): ask for the allocation of a placed order, then price it and record it (R1.1, R1.2).
     2	// The parent handles duplicates (R1.4) and the edition (R1.3) and passes the edition in.
     3	
     4	const fileJson = (files, p) => {
     5	  let v = files?.[p];
     6	  if (v === undefined) v = p.split('/').reduce((o, k) => (o ? o[k] : undefined), files);
     7	  if (typeof v === 'string') { try { v = JSON.parse(v); } catch { return null; } }
     8	  return v ?? null;
     9	};
    10	const rowsOf = v => (Array.isArray(v) ? v : Array.isArray(v?.rows) ? v.rows : Array.isArray(v?.items) ? v.items
    11	  : Array.isArray(v?.data) ? v.data : []);
    12	const plainItems = items => (items ?? []).map(i => ({ sku: String(i.sku), qty: Number(i.qty) }));
    13	
    14	// Σ qty × unitPriceMinor, plus the location's fee (none for an unavailable fulfilment) — R1.2.
    15	const priceOf = (ctx, edition, items, loc) => {
    16	  const catalog = rowsOf(fileJson(ctx.files, 'master/catalog.json'));
    17	  let sum = 0;
    18	  for (const it of items) {
    19	    const row = catalog.find(r => r.sku === it.sku);
    20	    if (!row || typeof row.unitPriceMinor !== 'number') throw new Error(`no unitPriceMinor for ${it.sku}`);
    21	    sum += it.qty * row.unitPriceMinor;
    22	  }
    23	  if (loc !== null) {
    24	    const fees = rowsOf(fileJson(ctx.files, `rulebook/${edition}/shipping-fees.json`));
    25	    const fee = fees.find(r => r.location === loc);
    26	    if (!fee || typeof fee.feeMinor !== 'number') throw new Error(`no feeMinor for location ${loc} in ${edition}`);
    27	    sum += fee.feeMinor;
    28	  }
    29	  return sum;
    30	};
    31	
    32	export function step(input, ctx) {
    33	  if (input.op === 'place') {
    34	    return {
    35	      output: { stage: 'allocating' },
    36	      effects: [{ system: 'inventory', op: 'allocate', args: { orderId: input.order.orderId } }],
    37	    };
    38	  }
    39	  if (input.op === 'allocated') {
    40	    const order = input.order;
    41	    const edition = input.edition;
    42	    const raw = input.plan?.fulfilments ?? [];
    43	    if (!raw.length) throw new Error('allocation has no fulfilments');
    44	    const fl = raw.map(f => {
    45	      const loc = f.location ?? null;
    46	      const items = plainItems(f.items);
    47	      const av = loc !== null && f.available !== false;
    48	      return { fid: String(f.fulfilmentId), loc: av ? loc : null, av, amt: priceOf(ctx, edition, items, av ? loc : null), items };
    49	    });
    50	    const total = fl.reduce((s, f) => s + f.amt, 0);
    51	    const customers = rowsOf(fileJson(ctx.files, 'master/customers.json'));
    52	    const cust = customers.find(c => c.customerId === order.customerId);
    53	    if (!cust || !cust.email) throw new Error(`no email for customer ${order.customerId}`);
    54	    return {
    55	      output: { fl, total, em: cust.email, cust: order.customerId, cur: order.currency, p: order.placedAt },
    56	      effects: [{
    57	        key: 'create', system: 'orders', op: 'create',
    58	        args: {
    59	          orderId: order.orderId, customerId: order.customerId, placedAt: order.placedAt, currency: order.currency,
    60	          items: plainItems(order.items),
    61	          fulfilments: fl.map(f => ({ fulfilmentId: f.fid, location: f.loc, items: f.items, amountMinor: f.amt })),
    62	          totalMinor: total,
    63	        },
    64	      }],
    65	    };
    66	  }
    67	  throw new Error(`intake: unknown op ${input.op}`);
    68	}
    69	
    70	export function onEvent(event, ctx) {
    71	  // the order record's result: nothing to do but keep the module instance quiet (the parent reads the outcome)
    72	  return { output: null };
    73	}

