  if (typeof v === 'string' && (p.minLength > v.length || p.maxLength < v.length)) return false;
  if (typeof v === 'number' && (p.minimum > v || p.maximum < v)) return false;
  return true;
};
const stem = k => String(k).toLowerCase().replace(/[^a-z0-9]/g, '');
const alike = (a, b) => {
  const x = stem(a), y = stem(b);
  return x.includes(y) || y.includes(x) || (x.length >= 4 && y.length >= 4 && x.slice(0, 4) === y.slice(0, 4));
