  if (sys === 'inventory.reserve') {
    const items = Array.isArray(p.items) ? p.items : Object.keys(S.res).filter(k => S.res[k].s === 'pend').map(sku => ({ key: `r.${sku}`, status: p.status, error: p.error }));
